export const auth = getAuth(app);
export const db = getFirestore(app);

// User-scoped Task Management
export const addTask = async (task, userId = "guest") => {
  try {
    const tasksCollection = collection(db, "Users", userId, "tasks");
    const docRef = await addDoc(tasksCollection, {
      text: task,
      completed: false,
      timestamp: new Date(),
      userId,
    });
    return docRef;
  } catch (error) {
    console.error("Error adding task: ", error);
    throw error;
  }
};

export const getTasks = async (userId = "guest") => {
  try {
    const tasksCollection = collection(db, "Users", userId, "tasks");
    const snapshot = await getDocs(tasksCollection);
    return snapshot.docs.map((doc) => ({
      id: doc.id,
      ...doc.data(),
    }));
  } catch (error) {
    console.error("Error fetching tasks: ", error);
    throw error;
  }
};

export const deleteTask = async (taskId, userId = "guest") => {
  try {
    const taskDoc = doc(db, "Users", userId, "tasks", taskId);
    await deleteDoc(taskDoc);
  } catch (error) {
    console.error("Error deleting task: ", error);
    throw error;
  }
};

export const completeTask = async (taskId, completed = true, userId = "guest") => {
  try {
    const taskDoc = doc(db, "Users", userId, "tasks", taskId);
    await updateDoc(taskDoc, { completed });
  } catch (error) {
    console.error("Error completing task: ", error);
    throw error;
  }
};

export const saveFeedback = async (feedback, userId = "anonymous") => {
  try {
    const feedbackCollection = collection(db, "feedbacks");
    const docRef = await addDoc(feedbackCollection, {
      feedback,
      userId,
      timestamp: new Date(),
    });
    return docRef;
  } catch (error) {
    console.error("Error saving feedback: ", error);
    throw error;
  }
};

// Save User Profile to Users/{uid}
export const saveUserInfo = async (userId, data) => {
  try {
    if (!userId) {
      throw new Error("User ID is required to update profile");
    }
    const userDocRef = doc(db, "Users", userId);
    await setDoc(userDocRef, {
      ...data,
      updatedAt: new Date(),
    }, { merge: true });
    return userDocRef;
  } catch (error) {
    console.error("Error saving user info: ", error);
    throw error;
  }
};

